-- 1. Messages from the website's contact form ("Prefer to write?"). Each one is also emailed to the alert address in the admin.
create table if not exists cms_messages (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  email text not null,
  whatsapp text not null default '',
  message text not null,
  stage text not null default '',
  page text not null default '',
  status text not null default 'new' check (status in ('new','read','replied','archived')),
  notes text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists cms_messages_status_idx on cms_messages (status, created_at desc);

-- 2. Sessions carry this number; changing a password or disabling an account bumps it, which signs out every old session.
alter table cms_users add column if not exists session_version int not null default 0;

-- 3. Pages that shipped without their own Google description (they fell back to the home page's). Only fills empty ones.
update cms_pages set seo = jsonb_set(seo, '{metaDescription}', to_jsonb($d$A 1 to 2 week Discovery Sprint turns your app idea into a clickable prototype, a clear feature list and a fixed quote before you build.$d$::text)) where path = '/services/discovery-sprint' and coalesce(seo->>'metaDescription', '') = '';
update cms_pages set published_seo = jsonb_set(published_seo, '{metaDescription}', to_jsonb($d$A 1 to 2 week Discovery Sprint turns your app idea into a clickable prototype, a clear feature list and a fixed quote before you build.$d$::text)) where path = '/services/discovery-sprint' and coalesce(published_seo->>'metaDescription', '') = '';
