update cms_pages set seo = jsonb_set(seo, '{metaDescription}', to_jsonb($d$Products we have taken from idea to launch, from the Nexuss family history platform to booking systems for Jara Beach Resort and Lufasi Lodges.$d$::text)) where path = '/our-work' and coalesce(seo->>'metaDescription', '') = '';
