-- 4. A Privacy policy page (both website forms link to it). Added as published; review the wording in the admin.
insert into cms_pages (title, path, status, sections, published_sections, seo, published_seo, has_unpublished_changes, published_at, sort_order)
values ('Privacy policy', '/privacy', 'published', $j$[{"key": "hero-c9axw7", "type": "hero", "label": "Hero", "visible": true, "fields": {"eyebrow": "PRIVACY", "eyebrowShort": "", "heading": "Privacy policy", "text": "How 24 Design Co. collects, uses and protects the details you share with us through this website. Last updated 13 November 2026.", "primaryButtonText": "", "primaryButtonLink": "", "secondaryButtonText": "", "secondaryButtonLink": "", "note": "", "image": "", "imageAlt": "", "panelTitle": "", "panelItems": [], "accentLast": false}}, {"key": "richText-28a4pj", "type": "richText", "label": "Who we are", "visible": true, "fields": {"eyebrow": "", "heading": "Who we are", "headingSize": "normal", "body": "24 Design Co. is a trading name of **24 Discovery Limited** (RC 1733408), a company registered in Nigeria. We are responsible for the personal data described here.\n\nFor any question about your data, email **info@24group.com.ng**.", "align": "left", "background": "white", "spacing": "normal"}}, {"key": "richText-71se3j", "type": "richText", "label": "What we collect", "visible": true, "fields": {"eyebrow": "", "heading": "What we collect", "headingSize": "normal", "body": "**When you book a free idea review:** your name, email address, phone number, company, a description of your idea, its stage, your budget range and how you heard about us.\n\n**When you send a message:** your name, email address, WhatsApp number (if you give one), what you are building and its stage.\n\n**When you browse the website:** if website analytics are switched on, Google Analytics records how the site is used (pages visited, device and approximate location). It does not tell us who you are.", "align": "left", "background": "white", "spacing": "normal"}}, {"key": "richText-trh48w", "type": "richText", "label": "How we use it", "visible": true, "fields": {"eyebrow": "", "heading": "How we use it", "headingSize": "normal", "body": "We use your details only to arrange and prepare for your call, to reply to your message, and to follow up about the project you asked us about. We do not sell your details or use them for unrelated marketing.\n\nOur legal basis is your consent when you submit a form, and our legitimate interest in answering enquiries about our services.", "align": "left", "background": "white", "spacing": "normal"}}, {"key": "richText-eex07q", "type": "richText", "label": "Who we share it with", "visible": true, "fields": {"eyebrow": "", "heading": "Who we share it with", "headingSize": "normal", "body": "We use trusted service providers to run the website and handle enquiries: our hosting and database providers, our email provider, Google Calendar and Google Meet for booked calls, and Google Analytics if it is switched on. They process your details on our behalf and only as needed to provide their service.\n\nSome of these providers store data outside Nigeria. Where that happens we rely on their contractual and security commitments to protect it.", "align": "left", "background": "white", "spacing": "normal"}}, {"key": "richText-qq0pwe", "type": "richText", "label": "How long we keep it", "visible": true, "fields": {"eyebrow": "", "heading": "How long we keep it", "headingSize": "normal", "body": "We keep enquiries and booking details for up to 24 months after our last contact, unless you become a client, in which case we keep them for as long as the work and our legal obligations require. You can ask us to delete them sooner.", "align": "left", "background": "white", "spacing": "normal"}}, {"key": "richText-mnuch1", "type": "richText", "label": "Your rights", "visible": true, "fields": {"eyebrow": "", "heading": "Your rights", "headingSize": "normal", "body": "You can ask to see the details we hold about you, correct them, delete them, or object to how we use them, and you can withdraw your consent at any time. Email **info@24group.com.ng** and we will reply within 30 days.\n\nIf you are not satisfied with our answer, you can complain to the Nigeria Data Protection Commission.", "align": "left", "background": "white", "spacing": "normal"}}, {"key": "richText-4ohjiz", "type": "richText", "label": "Security", "visible": true, "fields": {"eyebrow": "", "heading": "Keeping your details safe", "headingSize": "normal", "body": "Your details are sent over an encrypted connection and stored in a secured database. Only our team can see them, through a password-protected admin.", "align": "left", "background": "white", "spacing": "normal"}}]$j$::jsonb, $j$[{"key": "hero-c9axw7", "type": "hero", "label": "Hero", "visible": true, "fields": {"eyebrow": "PRIVACY", "eyebrowShort": "", "heading": "Privacy policy", "text": "How 24 Design Co. collects, uses and protects the details you share with us through this website. Last updated 13 November 2026.", "primaryButtonText": "", "primaryButtonLink": "", "secondaryButtonText": "", "secondaryButtonLink": "", "note": "", "image": "", "imageAlt": "", "panelTitle": "", "panelItems": [], "accentLast": false}}, {"key": "richText-28a4pj", "type": "richText", "label": "Who we are", "visible": true, "fields": {"eyebrow": "", "heading": "Who we are", "headingSize": "normal", "body": "24 Design Co. is a trading name of **24 Discovery Limited** (RC 1733408), a company registered in Nigeria. We are responsible for the personal data described here.\n\nFor any question about your data, email **info@24group.com.ng**.", "align": "left", "background": "white", "spacing": "normal"}}, {"key": "richText-71se3j", "type": "richText", "label": "What we collect", "visible": true, "fields": {"eyebrow": "", "heading": "What we collect", "headingSize": "normal", "body": "**When you book a free idea review:** your name, email address, phone number, company, a description of your idea, its stage, your budget range and how you heard about us.\n\n**When you send a message:** your name, email address, WhatsApp number (if you give one), what you are building and its stage.\n\n**When you browse the website:** if website analytics are switched on, Google Analytics records how the site is used (pages visited, device and approximate location). It does not tell us who you are.", "align": "left", "background": "white", "spacing": "normal"}}, {"key": "richText-trh48w", "type": "richText", "label": "How we use it", "visible": true, "fields": {"eyebrow": "", "heading": "How we use it", "headingSize": "normal", "body": "We use your details only to arrange and prepare for your call, to reply to your message, and to follow up about the project you asked us about. We do not sell your details or use them for unrelated marketing.\n\nOur legal basis is your consent when you submit a form, and our legitimate interest in answering enquiries about our services.", "align": "left", "background": "white", "spacing": "normal"}}, {"key": "richText-eex07q", "type": "richText", "label": "Who we share it with", "visible": true, "fields": {"eyebrow": "", "heading": "Who we share it with", "headingSize": "normal", "body": "We use trusted service providers to run the website and handle enquiries: our hosting and database providers, our email provider, Google Calendar and Google Meet for booked calls, and Google Analytics if it is switched on. They process your details on our behalf and only as needed to provide their service.\n\nSome of these providers store data outside Nigeria. Where that happens we rely on their contractual and security commitments to protect it.", "align": "left", "background": "white", "spacing": "normal"}}, {"key": "richText-qq0pwe", "type": "richText", "label": "How long we keep it", "visible": true, "fields": {"eyebrow": "", "heading": "How long we keep it", "headingSize": "normal", "body": "We keep enquiries and booking details for up to 24 months after our last contact, unless you become a client, in which case we keep them for as long as the work and our legal obligations require. You can ask us to delete them sooner.", "align": "left", "background": "white", "spacing": "normal"}}, {"key": "richText-mnuch1", "type": "richText", "label": "Your rights", "visible": true, "fields": {"eyebrow": "", "heading": "Your rights", "headingSize": "normal", "body": "You can ask to see the details we hold about you, correct them, delete them, or object to how we use them, and you can withdraw your consent at any time. Email **info@24group.com.ng** and we will reply within 30 days.\n\nIf you are not satisfied with our answer, you can complain to the Nigeria Data Protection Commission.", "align": "left", "background": "white", "spacing": "normal"}}, {"key": "richText-4ohjiz", "type": "richText", "label": "Security", "visible": true, "fields": {"eyebrow": "", "heading": "Keeping your details safe", "headingSize": "normal", "body": "Your details are sent over an encrypted connection and stored in a secured database. Only our team can see them, through a password-protected admin.", "align": "left", "background": "white", "spacing": "normal"}}]$j$::jsonb, $j${"metaTitle": "Privacy policy | 24 Design Co.", "metaDescription": "How 24 Design Co. collects, uses and protects the details you share when you book a free idea review or send us a message.", "ogImage": "", "noIndex": false}$j$::jsonb, $j${"metaTitle": "Privacy policy | 24 Design Co.", "metaDescription": "How 24 Design Co. collects, uses and protects the details you share when you book a free idea review or send us a message.", "ogImage": "", "noIndex": false}$j$::jsonb, false, now(),
  (select coalesce(max(sort_order), 0) + 1 from cms_pages))
on conflict (path) do nothing;

-- 5. Link the Privacy page from the footer of sites whose settings are already saved (new sites get it from the defaults).
update cms_settings set data = jsonb_set(data, '{footer,links}', coalesce(data->'footer'->'links', '[]'::jsonb) || '[{"label":"Privacy","url":"/privacy"}]'::jsonb, true), updated_at = now()
where singleton = 'site' and data ? 'footer' and not coalesce(data->'footer'->'links', '[]'::jsonb) @> '[{"url":"/privacy"}]'::jsonb;
